const s=[{'id':'2026-11-04','headline':'新技能幽影「黑暗笼罩」，封烟能封好几轮，结算能\x20360°\x20看烟','sections':[{'name':'新技能：幽影「黑暗笼罩」','items':['瓦创意工坊新增幽影\x20E：按\x20E\x20进暗影视角选点放烟，照游戏数据复刻','封烟训练可以选幽影了']},{'name':'封烟训练','items':['一个场景能封好几轮，每轮可换特工、出生点和队友语音','暮蝶、炼狱的烟能放上车顶、箱子顶','结算新增「360°\x20看烟」：烟停在封好的样子，拖动转一圈看效果，滚轮拉近拉远','编辑器里能看到每一轮的出生点，可一键放到画面正中']},{'name':'其他','items':['小球项目开局第一枪、新球刷出来时的卡顿做了优化','大厅右上角新增语言切换，可换英文界面']}]},{'id':'2026-11-03','headline':'新玩法封烟训练：暮蝶、炼狱放烟，编排器和训练清单上线，闪光照游戏重做','sections':[{'name':'新玩法：封烟训练','items':['瓦创意工坊新增暮蝶、炼狱的技能放烟，计分方式可选「封烟」：按\x20E\x20拿出地图选点，把烟封到作者标的位置，结算看封住几颗、偏差和用时（登录后出分）','开局前有队友语音情景，可开辅助瞄准「显示封烟位置」']},{'name':'瓦创意工坊','items':['新增「编排器」：几个敌人编成进攻方案，每波随机或按顺序上','生成器可设「走进范围才出」','不死鸟、斯凯、铁臂、K/O、夜露等闪光照游戏数据重做，K/O\x20能弹地','寻敌箭的扫描隔着烟看不见了','试玩里也能开辅助瞄准']},{'name':'大厅','items':['新增「训练清单」：自建、收藏、短码分享，能连续练，打完一张自动进下一张；官方清单「排位图池\x20·\x20预瞄」','瓦工坊新增实战、微调、热身、混烟、封烟等分类，一个项目可属多类']},{'name':'手感与修复','items':['武器名全部换成国服中文','幻影消音器照游戏改短，骇灵补上消音器','修复：进局就显示「已暂停」']}]},{'id':'2026-10-28','headline':'猎枭寻敌箭照游戏复刻，三把狙的开镜照游戏重做，烟雾能改时长和透明度','sections':[{'name':'瓦创意工坊','items':['新技能：猎枭「寻敌箭」照游戏整套复刻。做场景时在「场景规则」里勾上，玩的时候按\x20E\x20掏弓，弹道、反弹、两次扫描和透墙标记都和游戏一样','场景道具新增「寻敌箭」：摆一个敌方或友方的射手，照弹道射过来。敌方的箭会扫到你，可以打掉；友方的会标出敌人','烟雾可以改持续多久（2.5\x20秒到\x201\x20小时），也能调透明度，方便练混烟','「会开枪」新增一档：急停再打，摆射时只在急停站住时开枪','调度器放出来的复刻也会列在动作轨上']},{'name':'手感','items':['飞将、冥驹、莽侠的开镜照游戏复刻：镜身、镜孔边缘和黑色十字分划都和游戏一样']},{'name':'瓦工坊','items':['「辅助预瞄」改名「辅助瞄准」；摆了烟的项目里新增「烟雾透视」，开了不计排名']},{'name':'玩家创意工坊','items':['作品改成登录后才能玩；瓦工坊和玩家创意工坊的回放也要登录后才能看']},{'name':'其他','items':['地图和枪模换了新的加载方式，每样第一次用要重新下载一次，之后没改的不再重下']}]},{'id':'2026-10-25','headline':'左栏新增特殊活动抽《影之刃零》豪华版，18\x20把枪照游戏重做，刀能砍人了','sections':[{'name':'特殊活动','items':['左栏新增「特殊活动」：免费抽\x201\x20份《影之刃零》数字豪华版（Steam\x20国区\x20CDK）。在桌面版里完整打完一局瓦工坊，每天得\x201\x20张券，点「用券参加」才算。10\x20月\x2029\x20日\x2020:00\x20截止，当晚按体彩排列五和福彩\x203D\x20开奖，中奖另送「幸运锦鲤」徽章']},{'name':'手感','items':['18\x20把枪的第一人称动作照游戏整套重做，开枪、换弹、开镜、蹲起都和游戏一样，喷射的左右方向也照游戏改正了','狂徒等红点枪的开镜照游戏复刻，瞄具会翻开','刀能砍人了：左键轻砍，右键重击，背后砍伤害翻倍','敌人的枪口火光换成游戏里那套','同一局换回用过的枪，开镜不再卡一下']},{'name':'瓦创意工坊','items':['新增「动作复刻」：录下自己的一段走位，让敌人照着做','生成器可以隐藏，编辑和试玩时都当它不存在','右栏每个功能旁加了「教程」链接']},{'name':'大厅','items':['瓦工坊和小球官方精选的项目也能打分、写反馈了','收藏页点卡片直接拉出详情，不再跳走','修复：收藏偶尔显示全没了（收藏都在，只是没取到）','顶栏新增「点位库」（瞬投）']}]},{'id':'2026-10-23','headline':'新地图日落之城，敌人会抬头低头对着你，走路不再被小东西卡脚','sections':[{'name':'瓦创意工坊','items':['新增复刻地图：日落之城，当前排位图池的七张地图都齐了']},{'name':'手感','items':['开了「自动朝向」的敌人，你在高处或低处时会照游戏抬头低头对着你。修复：从下往上打高处敌人的脸，会被判成打身体','斜着贴边走上矮台不再卡脚（比如亚海悬城\x20A\x20点二楼的外沿），什么角度都是一步跨上去','所有地图：电线、草丛、垃圾袋、木箱和长椅的边这类游戏里能直接走过去的小东西，不再当成台阶或障碍，走过去不会再颠一下']},{'name':'大厅','items':['右上角新增消息铃铛，登录后能看站内通知']}]},{'id':'2026-10-22','headline':'敌人会下蹲了，急停项目有了状态条，拉伸方式新增「只拉界面」','sections':[{'name':'训练','items':['急停模式的项目，画面底部新增急停状态条：停下后还剩多久能开枪、停太久要先动一下，开不出枪时写明原因。参数设置\x20›\x20常规\x20›\x20界面里可以关','参数设置\x20›\x20视频\x20›\x20拉伸方式新增「只拉界面」：选\x204:3\x20等分辨率时人物和视野不变宽，只拉宽准星和狙击镜（原来只有真拉伸）']},{'name':'瓦创意工坊','items':['敌人新增「下蹲」行为：站住时、开枪之后、隔一段时间都能蹲，可以多选，各自设几成会蹲，蹲多久可调；下蹲过程和命中判定按游戏还原','摆射「随机左右」改成和游戏训练场的横移机器人一样：从出生点往随机一侧走出去，回到出生点再挑下一侧，不再原地抽一下','生成器的「生成延迟」「出场最小间隔」写清了各从什么时候算，以及「开局马上出、打倒后多等几秒」怎么配','修复：左上角地图卡片只有点文字才能换图']}]},{'id':'2026-10-21','headline':'小球工坊多了玩家场景，瓦工坊榜单看到前\x20100\x20名，烟雾能摆\x2050\x20颗','sections':[{'name':'小球工坊','items':['项目清单改名「官方精选」：都是玩家用瓦创意工坊做、社区反馈好的场景，卡片上写着作者，点名字进\x20TA\x20的主页','项目清单下面多了一排玩家做的小球场景：新作上架、本周热门、口碑之选','收藏页单独分出「小球工坊」一格','左栏「快速开始」可以点铅笔，换成自己常练的项目','还在审核的局，结算页写「已提交\x20·\x20在审核」，不再一直显示正在提交']},{'name':'瓦工坊','items':['完整榜单从前\x2010\x20名放到前\x20100\x20名','从这次起，以后更新时没改过的地图不用重新下载，进图更快']},{'name':'玩家创意工坊','items':['新作上架、本周热门、口碑之选改成页签切换','「新作上架」不会再整格消失：最近\x203\x20天上架的作品都能在这里找到']},{'name':'瓦创意工坊','items':['烟雾最多能摆\x2050\x20颗（原来\x208\x20颗），包点接人可以一直续烟','摆射新增「随机左右」，默认关闭']},{'name':'分享与主页','items':['回放分享页可以返回排行榜，回放画面更大，并写明是哪个项目','玩家主页新增「返回」按钮','大厅每个页签都有了自己的网址：刷新不会跳回瓦工坊，也能把链接直接发给朋友']}]},{'id':'2026-10-19','headline':'新增小球工坊，玩家创意工坊有了推荐，训练记录改版，枪的手感更像游戏','sections':[{'name':'小球工坊','items':['顶栏新增「小球工坊」：网格射击、六目标、三目标，打完当场核算上榜，排行榜在标题旁边','新增反应加分：打掉一个后越快打掉下一个，加分越多','「参数」改成边调边看的大弹窗，小球颜色可以自选','开局前倒数\x200.5～3\x20秒，设置里可以关掉','可以看本局回放、分享回放']},{'name':'训练记录','items':['改版「战绩档案」：日历、本周、最近\x2010\x20局、我的项目']},{'name':'玩家创意工坊','items':['新增推荐：精选轮播、新作上架、本周热门、口碑之选']},{'name':'瓦创意工坊','items':['新增使用教程：六关新手教程加完整手册','场景规则新增「漏靶扣分」','试玩里改设置马上生效']},{'name':'手感','items':['走路、跑步时枪会像游戏里一样晃','点击那一刻的准星更准，按下后的手抖不再算进这一枪','第一人称曳光按游戏重做','抬头低头可以到接近垂直']},{'name':'其他','items':['顶栏新增「赛事赛程」（号角），「下载桌面版」挪到底栏','修复同时开着几个页面时设置互相覆盖']}]},{'id':'2026-10-17','headline':'新增玩家投票，预瞄项目结算有了预瞄分，创意工坊作品可以评分，瓦创意工坊多了两张复刻地图','sections':[{'name':'玩家投票','items':['顶栏新增「玩家投票」：接下来先做什么由大家投票决定，登录并打够局数就能投']},{'name':'瓦工坊','items':['预瞄项目结算新增「预瞄分」：看敌人露头时准星离头多远、头线压得准不准，附点位图','跟枪改成按子弹线判断有没有压在靶上']},{'name':'玩家创意工坊','items':['作品可以评\x201～5\x20星、写反馈；超过\x2010\x20人评分才显示平均分，作者看得到反馈、看不到是谁写的']},{'name':'瓦创意工坊','items':['新增两张复刻地图：盐海矿镇、源工重镇（传送门能用）','新建场景可以选小球模板（网格、区域随机、点位调度），调度器也能放小球','可以把球的大小、距离、同时几个等参数开放给玩家调，玩家在开局屏或\x20TAB\x20里改，改过参数的局不计排名','「摆射」的急停改成和游戏训练场的横移\x20bot\x20一样']},{'name':'设置','items':['新增「反转鼠标」（上下）：参数设置\x20›\x20常规\x20›\x20鼠标','击杀图标可以单独关：参数设置\x20›\x20训练场\x20›\x20目标','去掉「画面比例」，画面比例跟着分辨率走']},{'name':'修复','items':['连点太快时偶尔开不出枪','幽邃地窟的穿墙改按墙的材质算（之前一律按混凝土）','英文系统的浏览器里部分文字显示成英文']}]},{'id':'2026-10-15','headline':'计分改成看每次击杀前空了几枪，预瞄项目加了辅助预瞄，瓦创意工坊可以摆烟了','sections':[{'name':'计分','items':['改成看每次击杀前空了几枪：一枪没空\x201000\x20分，空\x201\x20枪\x20600，空\x202\x20枪及以上\x20300；空枪不再扣分，跟枪照旧']},{'name':'瓦工坊','items':['预瞄项目新增「辅助预瞄」，入场屏、TAB、ESC\x20都能打开：击杀顺序号码（标在敌人头顶，换路线会自动重排）、准星到下一个人头的连线、墙上的头线、小地图敌人位置，可以分别开关','简单难度照常上榜；其他难度开着任意一项，这局不计排名','击杀音效新增「2021全球冠军赛」；打倒敌人时屏幕下方弹出击杀图标，跟着选的那套皮肤走','跟枪类项目结算不再是\x200\x20分']},{'name':'瓦创意工坊','items':['新场景道具「烟雾」：炼狱、幽影、星礈、暮蝶、迷核、捷风的烟，和游戏同款特效；可以设第几秒放、敌方还是友方。烟挡视线和闪光，不挡子弹','画面底部新增时间轴，拖动就能改每颗烟什么时候放','修复：在视口里拖动场景道具后位置没存上、会跳回原处']},{'name':'其他','items':['登录过期时不再跳到别的页面，原地切成游客并弹出登录框','创意工坊作品封面现在能正常显示了']}]},{'id':'2026-10-12','headline':'人物模型换成游戏同款着色，小地图六张图齐了，创意工坊作品可由官方直接优化','sections':[{'name':'玩家创意工坊','items':['作品可能会由官方直接优化（比如调时长、敌人数量），优化过的作品署名写「作者、官方」','作品被官方优化过，作者要先在编辑器里换成线上这一版才能继续更新','《作品发布协议》更新到第\x202\x20版，下次发布前会请你重新确认']},{'name':'瓦创意工坊','items':['巡逻路线可以开「急停刹车」：停留点和终点会像游戏里那样急停站稳','新建场景默认\x2060\x20秒、血量归零即结束；新建敌人模板默认受击减速','瓦工坊可以有不带地图的「训练场」项目，新增「基础训练」类型']},{'name':'训练','items':['人物模型换成游戏同款着色，更清楚、更有立体感','莲华古城、幽邃地窟有小地图了；亚海悬城、霓虹町、隐世修所的小地图朝向和游戏一致','结算页上榜那一行显示本局成绩、个人最高和第几名','设置里加了「默认行走」；刀的检视可以绑鼠标侧键；桌面版可以设帧率上限（也能自定义）']},{'name':'其他','items':['分享出去的本地录像现在会显示分数和本局数据','桌面版改在\x20KOOK「桌面端下载」频道下载']}]},{'id':'2026-10-11','headline':'玩家创意工坊上线：你做的场景，审核通过后所有人都能玩','sections':[{'name':'玩家创意工坊','items':['顶栏新增「玩家创意工坊」：在瓦创意工坊搭好场景，点「发布」，审核通过后所有人都能玩，署名是你','每件作品有自己的积分榜（总榜\x20/\x20本周\x20/\x20今日），打完一局结算页直接看名次','作品可以收藏、复制链接发给朋友；「我的投稿」里能看审核进度','作品的训练记录存在这台电脑上，结算页能看比上一局、个人最佳和走势']},{'name':'瓦创意工坊','items':['试玩时顶部有了和瓦工坊一样的计分板（得分\x20/\x20时间\x20/\x20命中率）','顶栏加了「作品管理」，一键打开我的投稿']},{'name':'其他','items':['个人中心加了「退出登录」','瓦工坊卡片上的游玩次数统计更准了']}]},{'id':'2026-10-10','headline':'瓦工坊不用一直往下翻了，刀的整套动作按游戏重做','sections':[{'name':'瓦工坊','items':['项目多了不用一直往下翻：每张图最多两排，两侧按钮左右翻页；最上面一排「继续练」是你最近玩过的','筛选可以只看「没玩过」「收藏」，能按推荐\x20/\x20最热\x20/\x20最新排序；往下滚时选图和筛选吸在顶上','幽邃地窟掉下悬崖会提示「坠崖身亡」并重新开始']},{'name':'手感与画面','items':['刀的整套动作按游戏重做：待机、三段轻砍、重击、检视（Y\x20键），走跑动作和刀刃朝向也改对了','手枪把模型视野调大时，左下角不再露出一截手臂','地图光照文件缩小八成，进图更快，画面几乎看不出差别']},{'name':'排行榜','items':['人物跟枪榜只收\x2010\x20月\x202\x20日（改按子弹落点计分）以后的成绩，之前的成绩照常保留，只是不进这张榜']},{'name':'其他','items':['左栏新增「更新日志」，有新更新时打开网页会弹出来','官方\x20KOOK\x20换了新频道（频道\x20ID\x203185），满了的\x20QQ\x20群收起来了','浏览器标签页换成瞄准专家自己的准星图标']}]},{'id':'2026-10-09','headline':'移动按游戏重做，打移动的敌人不再吞子弹，新地图幽邃地窟','sections':[{'name':'手感','items':['移动按游戏重新还原：起步、急停、跳跃、落地减速、移动散布、中弹减速，人物和靶子同一套','狙击枪开镜按游戏数据，冥驹开镜首发不再偏；霰弹枪弹丸分布更匀','开枪的敌人散布也按游戏；敌人复活从静止起步，不再一出来就满速','修正幻象、斗牛犬、戍卫的跳射散布']},{'name':'修复','items':['打移动敌人「吞子弹」：改按你开枪那一刻看到的画面判定','同一瞬间对枪算你先开，不再同归于尽']},{'name':'瓦工坊','items':['计分放宽：空枪每发扣\x2020（原\x2050），漏掉敌人不再另扣\x20500，扣分最多扣击杀分的一半；已有成绩不变','TAB\x20菜单可「暂停计时」，慢慢熟悉地图（开过的那局不上榜）','底栏搜索能搜瓦工坊项目']},{'name':'瓦创意工坊','items':['新地图「幽邃地窟」','穿越可开「急停刹车」；调度器支持摆射点','「落地」不会再停在半空']},{'name':'其他','items':['霰弹枪、狙击枪有开火火光了；正义不再冒两团烟','参数设置可关击中特效、击中/击杀音效']}]},{'id':'2026-10-07','headline':'后坐力全面重做，12\x20把枪有了原版枪口火光','sections':[{'name':'手感','items':['后坐力全面重做，按游戏文件还原散布、上抬、左右摆和停火回落，压枪轨迹和游戏一致','开枪时画面跟着后坐上抬一部分，每发有轻微弹跳，后面的子弹要自己压']},{'name':'画面','items':['新增枪口火光：12\x20把枪都有游戏原版火光，消音枪是消音火光（霰弹、狙暂时没有）','人形靶横向移动改成交叉步','人形靶命中判定按游戏重新导出，修正高度和朝向偏差；蹲姿视角高度和游戏一致']},{'name':'瓦工坊','items':['背闪新增\x20K/O、瑞娜、铁臂、斯凯、夜露、维斯的闪光，闪光有声音了','推荐位改成轮播；天枢云阙出生点屏障不再挡视线和闪光']},{'name':'设置','items':['新增开镜灵敏度、狙击开镜灵敏度','可以单独设置开镜准星和狙击镜中心点；准星码和游戏导入导出一致']},{'name':'其他','items':['回放准星轨迹修正','国内加载更快','以前的成绩和回放都保留']}]},{'id':'2026-10-05','headline':'子弹可以穿墙了，小地图能看到\x20bot\x20在哪','sections':[{'name':'子弹可以穿墙了','items':['瓦工坊和瓦创意工坊的地图里按材质算：玻璃、泥土、木头好穿，混凝土次之，金属最难；穿得越厚伤害越低','枪分低\x20/\x20中\x20/\x20高三档穿透力，数据取自游戏','子弹能穿过一个人打中后面的人；植物、藤蔓这类装饰不再挡子弹和走位']},{'name':'瓦工坊：显示\x20bot\x20位置','items':['小地图标出\x20bot，打倒变灰叉','显示设置里可选档位，默认只在简单项目显示；其他项目开着打不计排名','没打完时，结算页会标出剩下的\x20bot\x20在哪']},{'name':'瓦工坊：沿用上局装备','items':['买过的枪和护甲，同一项目下一局直接带着，照常上榜；想换回买「原配」']},{'name':'其他','items':['瓦工坊项目可以收藏了','新增「分辨率」设置，可自定义宽×高','4:3\x20等拉伸比例的视野改成和游戏一样（之前是反的）','「击杀音效」单独一栏，默认盖亚的复仇','小球项目只改颜色照常上榜','手机打开改成「掌上看台」，能看项目和排行榜','修复小球新球从准星处滑过去的问题','卡在「正在载入训练场」时会显示等了几秒，可直接返回']}]},{'id':'2026-10-04','headline':'可以切刀了，新增两套皮肤击杀音','sections':[{'name':'瓦工坊\x20/\x20瓦创意工坊','items':['新增切刀：3\x20拿刀、1\x20切回枪（可改键），枪和刀都有拿出动作，拿好前不能开火，拿刀跑得更快','新增皮肤击杀音：盖亚的复仇、混沌序曲（参数设置→目标击中音效），1～5\x20杀逐级变化，之后循环']},{'name':'手感\x20/\x20计分','items':['修复蹲拉时突然加速：按下蹲立即按蹲姿算移速和准度','人物跟枪按部位计分：压头满分，压身体、腿算一半']},{'name':'排行榜','items':['收录全部玩家，可查自己的名次及前后各\x2010\x20名','修复频繁重开冲纪录后成绩不进榜']},{'name':'灵敏度测试','items':['「灵敏度调试」改名「灵敏度测试」，入口更醒目，开测前增加原理和测法说明']},{'name':'桌面版\x200.0.13（群文件下载）','items':['个人中心新增「我的工位」，自动识别外设和电脑配置','修复桌面版隔一会儿自动暂停','旧版本打开会提示更新']}]},{'id':'2026-10-02','headline':'瓦工坊上线排行榜，可以买枪买甲了','sections':[{'name':'瓦工坊上线排行榜','items':['每个项目都有今日\x20/\x20本周\x20/\x20总榜','卡片上能看到有多少人打过、自己的名次，翻到背面能看前三名','名场面按通关用时排，其他项目按分数排','想上榜请先登录再开打：没登录时打的局、这次更新之前打的局都不会进榜','上榜成绩会经过系统复核，异常成绩会被撤下']},{'name':'我的记录','items':['每个瓦工坊项目都能查看自己打过的每一局']},{'name':'买枪买甲','items':['瓦工坊里按\x20B\x20打开购买菜单，可以换枪、买护甲（个别项目不开放）','血量改成\x20100\x20血\x20+\x20护甲，和游戏里一样；默认开局穿重甲，总共还是\x20150，难度不变','对局里的血量、护甲、弹药显示重新做了']},{'name':'其他','items':['瓦工坊里每把枪都换上了各自的开枪声','修复：带奇乐大招「全面封锁」的场景，触发大招后回放存不下来的问题']}]}];function t(b){const [c,d,f]=b['slice'](0x0,0xa)['split']('-')['map'](Number);return{'year':c,'month':d,'day':f};}function a(b){return b['sections']['reduce']((c,d)=>c+d['items']['length'],0x0);}export{s as C,a,t as c};